// Registruje View do kalalogu (ale nevim co to znamena)
// Kazdopadne roz:Doklad je viewID kterym se na nej budu odkazovat a zbytek je definice objektu ktery zastupuje
Gordic.Previews.register("roz:Doklad", {
    // Ověřování, zda je řádek kompletní
    canRender: function (dto) {
        debugger;
        return dto.ixp != null;
    },
    // Samotné vykreslení náhledu
    render: function (div, dto) {
        debugger;
        // Test a doplneni promennych z DTO        
        // div je zaslany element jako parametr funkce (bude to div, kam se umisti preview), udelej z nej JQuery objekt a uloz si odkaz
        var currentElement = $(div);
        // div vycisti a zacni do neho ukladat HTML - tj. vlozim nadpis a podtrhu ho
        currentElement.empty().append("<h2 class='g-state-text g-state-active' style='margin: 0.5rem;'>Doklad ROZ " + dto.ixp + "</h2><hr style='margin: 0.5rem; opacity: 0.2;'/>");
        // Toto zrejme udelat tlacitko pro odkaz ?
        Gordic.Previews.displayLinkButton(div, dto);
        // Toto vytvori novy div a za nej prida nadpis vytoreny pred chvili
        $("<div class='gform--view-mode'>").appendTo(currentElement)
            .gform("setup", { layoutDescriptor: "L1M1S1, breaks-300-400" })
            .gformsection("create")
            .gpidbar({ pid: dto.ixp })
            .gformsection("create")
            //.gformrow("addFieldsRow", "jres:30250267").gformtext(dto.dat_evid==null?"": Gordic.Templates.Formatters.date(parseDate(dto.dat_evid)), "bold")                        // RC 29750108 : Datum evidence //RC 30250267 : Nepřečtený doklad
            //.gformrow("addFieldsRow", "jres:30250297").gformtext(dto.rok===null?"":Gordic.Templates.Formatters.date(new Date(dto.rok, dto.mesic, dto.den)), "bold")//RC 30250297 : Převzít
            .gformrow("addFieldsRow", "jres:30150033").gformtext(dto.ac_ixe, "bold") //RC 30150033 : Č.dokladu
            .gformrow("addFieldsRow", "jres:30150011").gformtext(dto.ac_ag, "bold") //RC 30150011 : Agendové číslo
            .gformrow("addFieldsRow", "jres:30150010").gformtext(dto.ac, "bold") //RC 30150010 : Evidenční číslo
            //.gformrow("addFieldsRow", "jres:30250093").gformtext("<b class='g-state-text g-state-info'>" + dto.ktgTypNazev + "</b>", "bold")   //RC 30250093 : Převod RZ do rezervního fondu
            .gformrow("addFieldsRow", "jres:30150055").gformtext("" + (dto.drd === null ? "" : dto.drd), "bold") //RC 30150055 : Druh dokladu
            //.gformsection("create")
            //.gformrow("addFieldsRow", "jres:30250092").gformtext("<b class='g-state-text g-state-info'>" + dto.stav_txt  + "</b>", "bold") // RC 29750113 : Stav dokladu //RC 30250092 : Mimorozpočtové prostředky
            //.gformsection("create")
            //.gformrow("addFieldsRow", "jres:30250294").gformtext(Gordic.Templates.Formatters.number(parseDecimal(dto.c), "C") +" CZK")   //RC 30250294 : Vybrané doklady
            //.gformrow("addFieldsRow", "jres:30250295").gformtext(Gordic.Templates.Formatters.number(parseDecimal(dto.c0 === null || typeof dto.c0 === "undefined"? 0 : dto.c0), "C") + " CZK") //RC 30250295 : Zadání
            //.gformrow("addFieldsRow", "jres:30250296").gformtext(Gordic.Templates.Formatters.number(parseDecimal(dto.c1 === null || typeof dto.c1 === "undefined" ? 0 : dto.c1), "C") + " CZK") //RC 30250296 : Akce provede převzetí vybraných (zaškrtnutých) dokladů od jiného zpracovatele. Při převzetí je případně možné změnit Kompetenta dokladu.
            //.gformrow("addFieldsRow", "jres:30250023").gformtext(dto.ixs_fun_nazev, "bold") //RC 30250023 : realizováno;
            .gformsection("create")
            .gformrow("addFieldsRow", "jres:30150037").gformtext(dto.popis, "bold"); //RC 30150037 : Popis
        currentElement.resize().find(".gform-section").children("label").first().addClass("g-state-text g-state-error");
    }
});
